        function openEmployeeModal(name) {
            const empEntries = RAW_DATA.filter(r => r.PERSONA === name);
            if (!empEntries.length) return;

            const modal = document.getElementById('employee-modal');
            modal.classList.remove('hidden');

            const initials = name.split(' ').map(n => n[0]).join('').substring(0,2);
            document.getElementById('emp-modal-avatar').innerText = initials;
            document.getElementById('emp-modal-name').innerText = name;

            const contracts = Array.from(new Set(empEntries.map(r => translateContract(r.CONTRATTO)))).join(', ');
            const functions = Array.from(new Set(empEntries.map(r => translateFunction(r.FUNZIONE)))).join(', ');
            document.getElementById('emp-modal-contract').innerText = contracts;
            document.getElementById('emp-modal-function').innerText = functions;

            const totalCost = empEntries.reduce((a,b) => a + b['COSTO AZIENDA'], 0);
            const monthsCount = new Set(empEntries.map(r => `${r.ANNO}-${r.MESE}`)).size;
            const avgCost = totalCost / (monthsCount || 1);

            document.getElementById('emp-modal-total-cost').innerText = formatEuro(totalCost);
            document.getElementById('emp-modal-avg-cost').innerText = formatEuro(avgCost);
            document.getElementById('emp-modal-active-months').innerText = `${monthsCount} / 20`;

            const tbody = document.getElementById('emp-modal-table-body');
            tbody.innerHTML = '';
            empEntries.sort((a,b) => b.ANNO - a.ANNO || MONTHS_ORDER.indexOf(b.MESE) - MONTHS_ORDER.indexOf(a.MESE)).forEach(r => {
                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td class="px-3 py-1.5 font-bold">${r.ANNO}</td>
                    <td class="px-3 py-1.5">${translateMonth(r.MESE)}</td>
                    <td class="px-3 py-1.5">${translateContract(r.CONTRATTO)}</td>
                    <td class="px-3 py-1.5">${translateFunction(r.FUNZIONE)}</td>
                    <td class="px-3 py-1.5 text-right font-extrabold text-indigo-600 dark:text-indigo-400">${formatEuro(r['COSTO AZIENDA'])}</td>
                `;
                tbody.appendChild(tr);
            });

            const ctx = document.getElementById('chart-employee-detail').getContext('2d');
            const data2025 = MONTHS_ORDER.map(m => {
                const row = empEntries.find(r => r.ANNO === 2025 && r.MESE === m);
                return row ? row['COSTO AZIENDA'] : 0;
            });
            const data2026 = MONTHS_ORDER.map(m => {
                const row = empEntries.find(r => r.ANNO === 2026 && r.MESE === m);
                return row ? row['COSTO AZIENDA'] : null;
            });

            if (chartEmployeeDetailInstance) chartEmployeeDetailInstance.destroy();

            chartEmployeeDetailInstance = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: MONTHS_ORDER.map(m => translateMonth(m).substring(0,3)),
                    datasets: [
                        { label: '2025 (€)', data: data2025, borderColor: '#6366f1', tension: 0.3, fill: false },
                        { label: '2026 (€)', data: data2026, borderColor: '#10b981', tension: 0.3, fill: false }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: { ticks: { callback: v => '€' + v } }
                    }
                }
            });
        }

