        // --- DATATABLE LOGIC ---

        function sortDataTable(col) {
            if (dtSortCol === col) {
                dtSortAsc = !dtSortAsc;
            } else {
                dtSortCol = col;
                dtSortAsc = true;
            }
            renderDataTable();
        }

        function renderDataTable() {
            const tbody = document.getElementById('datatable-body');
            tbody.innerHTML = '';

            let sorted = [...FILTERED_DATA];
            sorted.sort((a,b) => {
                let valA = a[dtSortCol];
                let valB = b[dtSortCol];
                if (typeof valA === 'string') valA = valA.toLowerCase();
                if (typeof valB === 'string') valB = valB.toLowerCase();
                if (valA < valB) return dtSortAsc ? -1 : 1;
                if (valA > valB) return dtSortAsc ? 1 : -1;
                return 0;
            });

            document.getElementById('datatable-count').innerText = sorted.length.toLocaleString('en-US');

            const totalPages = Math.ceil(sorted.length / dtPageSize) || 1;
            if (dtCurrentPage > totalPages) dtCurrentPage = totalPages;

            const startIdx = (dtCurrentPage - 1) * dtPageSize;
            const pageData = sorted.slice(startIdx, startIdx + dtPageSize);

            pageData.forEach(r => {
                const tr = document.createElement('tr');
                tr.className = 'hover:bg-slate-50 dark:hover:bg-slate-800/50 transition';
                tr.innerHTML = `
                    <td class="px-4 py-2.5 font-bold">${translateMonth(r.MESE)}</td>
                    <td class="px-4 py-2.5 font-semibold text-indigo-600 dark:text-indigo-400">${r.ANNO}</td>
                    <td class="px-4 py-2.5 font-bold text-slate-900 dark:text-white cursor-pointer hover:underline" onclick="openEmployeeModal('${r.PERSONA.replace(/'/g, "\\'")}')">${r.PERSONA}</td>
                    <td class="px-4 py-2.5"><span class="px-2 py-0.5 rounded bg-blue-50 dark:bg-blue-950 text-blue-700 dark:text-blue-300 font-bold text-[10px]">${translateContract(r.CONTRATTO)}</span></td>
                    <td class="px-4 py-2.5"><span class="px-2 py-0.5 rounded bg-purple-50 dark:bg-purple-950 text-purple-700 dark:text-purple-300 font-bold text-[10px]">${translateFunction(r.FUNZIONE)}</span></td>
                    <td class="px-4 py-2.5 text-right font-extrabold text-slate-900 dark:text-white">${formatEuro(r['COSTO AZIENDA'])}</td>
                `;
                tbody.appendChild(tr);
            });

            document.getElementById('datatable-info').innerText = `Page ${dtCurrentPage} of ${totalPages}`;
            document.getElementById('btn-page-prev').disabled = dtCurrentPage === 1;
            document.getElementById('btn-page-next').disabled = dtCurrentPage === totalPages;
        }

        // Export Functions
        function exportToExcel() {
            const translatedData = FILTERED_DATA.map(r => ({
                'Month': translateMonth(r.MESE),
                'Year': r.ANNO,
                'Staff Member': r.PERSONA,
                'Contract': translateContract(r.CONTRATTO),
                'Function': translateFunction(r.FUNZIONE),
                'Company Cost (€)': r['COSTO AZIENDA']
            }));
            const worksheet = XLSX.utils.json_to_sheet(translatedData);
            const workbook = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(workbook, worksheet, "Labor Cost");
            XLSX.writeFile(workbook, `Labor_Cost_Export_${new Date().toISOString().slice(0,10)}.xlsx`);
        }

        function exportToCSV() {
            const headers = ['Month', 'Year', 'Staff Member', 'Contract', 'Function', 'Company Cost (€)'];
            const rows = FILTERED_DATA.map(r => [translateMonth(r.MESE), r.ANNO, `"${r.PERSONA}"`, `"${translateContract(r.CONTRATTO)}"`, `"${translateFunction(r.FUNZIONE)}"`, r['COSTO AZIENDA']]);
            let csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `Labor_Cost_Export_${new Date().toISOString().slice(0,10)}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        // --- SIMULATOR & FORECAST ---

        function renderSimulator() {
            const pctVal = parseFloat(document.getElementById('sim-pct').value) || 0;
            const monthlyEstimate = parseFloat(document.getElementById('sim-forecast-monthly').value) || 41918;

            const sum2026Actual = RAW_DATA.filter(r => r.ANNO === 2026).reduce((a,b) => a + b['COSTO AZIENDA'], 0);
            const forecast4M = monthlyEstimate * 4;
            const baseFull2026 = sum2026Actual + forecast4M;

            const simulatedFull2026 = baseFull2026 * (1 + (pctVal / 100));
            const sum2025Actual = RAW_DATA.filter(r => r.ANNO === 2025).reduce((a,b) => a + b['COSTO AZIENDA'], 0);
            const deltaVS2025 = simulatedFull2026 - sum2025Actual;
            const deltaPctVS2025 = ((deltaVS2025 / sum2025Actual) * 100).toFixed(2);

            document.getElementById('sim-projected-2026').innerText = formatEuro(simulatedFull2026);
            document.getElementById('sim-delta-val').innerText = `${deltaVS2025 >= 0 ? '+' : ''}${formatEuro(deltaVS2025)} (${deltaVS2025 >= 0 ? '+' : ''}${deltaPctVS2025}%)`;

            const ctx = document.getElementById('chart-sim-forecast').getContext('2d');
            const isDark = document.documentElement.classList.contains('dark');
            const gridColor = isDark ? 'rgba(51, 65, 85, 0.3)' : 'rgba(226, 232, 240, 0.8)';
            const textColor = isDark ? '#94a3b8' : '#64748b';

            if (chartSimForecastInstance) chartSimForecastInstance.destroy();

            chartSimForecastInstance = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: ['2025 Actual (12M)', '2026 Actual (8M)', '2026 Forecast (12M)', '2026 Simulated Scenario (12M)'],
                    datasets: [{
                        label: 'Company Cost (€)',
                        data: [sum2025Actual, sum2026Actual, baseFull2026, Math.round(simulatedFull2026)],
                        backgroundColor: ['#6366f1', '#3b82f6', '#10b981', '#f59e0b'],
                        borderRadius: 8
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { display: false },
                        tooltip: { callbacks: { label: ctx => `Total: ${formatEuro(ctx.raw)}` } }
                    },
                    scales: {
                        x: { grid: { color: gridColor }, ticks: { color: textColor, font: { size: 10, weight: 600 } } },
                        y: { grid: { color: gridColor }, ticks: { color: textColor, font: { size: 10 }, callback: v => '€' + (v/1000) + 'k' } }
                    }
                }
            });
        }
    